"""A00 m81268: five language-bearing redraws and39 inspected originals.

Car image bytes remain unchanged. SVG viewports display only photo regions;
all source labels are replaced with Gujarati semantic HTML. No runtime reads.
"""
from html import escape
from localized_place_value import FONT, INK, TEAL, PALE, _uid, _outer
from localized_a10_algebra import _power_diagram, _m

PREFIX = 'CNX_BMath_Figure_02_01_'
VERIFIED_MATH_ONLY = frozenset(PREFIX + suffix for suffix in (
    '001.jpg', '002.jpg',
    '011_img-01.png', '011_img-02.png', '011_img-03.png', '011_img-04.png',
    '012_img-01.png', '012_img-02.png', '012_img-03.png', '012_img-04.png',
    '013_img-01.png', '013_img-02.png', '013_img-03.png',
    '014_img-01.png', '014_img-02.png', '014_img-03.png',
    '015_img-01.png', '015_img-02.png', '015_img-03.png', '015_img-04.png', '015_img-05.png',
    '016_img-01.png', '016_img-02.png', '016_img-03.png', '016_img-04.png', '016_img-05.png',
    '016_img-06.png', '016_img-07.png', '016_img-08.png', '016_img-09.png', '016_img-10.png',
    '017_img-01.png', '017_img-02.png', '017_img-03.png', '017_img-04.png', '017_img-05.png', '017_img-06.png',
    '018_img.jpg', '019_img.jpg',
))
CARS = ('પ્રિયસ', 'મિની કૂપર', 'ટોયોટા કોરોલા', 'વર્સા', 'હોન્ડા ફિટ')
MPG = (48, 27, 28, 26, 27)
# x,y,width,height in the original632x117 JPEG. Headers end above y20;
# fuel labels/data start at y81. All five complete photos lie within20..78.
PHOTO_VIEWPORTS = ((110,20,100,58),(213,20,102,58),(318,20,102,58),(423,20,102,58),(528,20,102,58))
CAR_IMAGE_SHA256 = '81f7103397afbc78b766dd95d227010a6d3df89fe874d81fd9366d1fe68ce0b3'
CAR_IMAGE_BASE64 = ''


def _cars(alt, uid):
    image_id = uid + '-source-photos'
    body = (f'<svg xmlns="http://www.w3.org/2000/svg" width="0" height="0" aria-hidden="true" '
            'style="position:absolute;overflow:hidden"><defs>'
            f'<image id="{image_id}" width="632" height="117" href="data:image/jpeg;base64,{CAR_IMAGE_BASE64}"/>'
            '</defs></svg>')
    body += ('<div role="region" aria-label="કારની ઇંધણ કાર્યક્ષમતાનું કોષ્ટક; આડું સરકાવી શકાય છે" '
             'tabindex="0" style="overflow-x:auto;max-width:100%">'
             '<table style="border-collapse:collapse;min-width:680px;width:100%;table-layout:fixed;text-align:center">'
             '<tbody><tr><th scope="row" style="border:1px solid #08656b;padding:8px;background:#edf6f4;width:140px">કાર</th>')
    for car, viewport in zip(CARS, PHOTO_VIEWPORTS):
        box = ' '.join(map(str,viewport))
        body += (f'<th scope="col" style="border:1px solid {TEAL};padding:5px;font-size:16px">{car}'
                 f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{box}" aria-hidden="true" '
                 'style="display:block;width:100%;height:auto;margin-top:4px;overflow:hidden">'
                 f'<use href="#{image_id}"/></svg></th>')
    body += ('</tr><tr><th scope="row" style="border:1px solid #08656b;padding:8px;background:#edf6f4;font-size:16px">'
             'ઇંધણ કાર્યક્ષમતા<br>(ગૅલન દીઠ માઈલ)</th>')
    for value in MPG:
        body += f'<td style="border:1px solid {TEAL};padding:8px;font-size:22px">{value}</td>'
    return _outer(body + '</tr></tbody></table></div>',alt,uid,'a00-algebra-car-table')


def _general(alt,uid):
    body = _power_diagram('a','n',uid+'-power')
    body += '<div style="display:flex;justify-content:center;align-items:flex-start;gap:8px;flex-wrap:wrap">'
    body += _m('<msup><mi>a</mi><mi>n</mi></msup><mo>=</mo>')
    body += '<div style="text-align:center;max-width:100%">'
    body += _m('<mi>a</mi><mo>·</mo><mi>a</mi><mo>·</mo><mi>a</mi><mo>·</mo><mo>…</mo><mo>·</mo><mi>a</mi>')
    body += (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 24" aria-hidden="true" '
             'style="display:block;width:100%;height:24px">'
             f'<path d="M2 2 V8 Q2 12 8 12 H107 Q120 12 120 22 Q120 12 133 12 H232 Q238 12 238 8 V2" '
             f'fill="none" stroke="{TEAL}" stroke-width="1.6"/></svg>')
    body += f'<p style="margin:0;color:{TEAL}">'+_m('<mi>n</mi>',TEAL)+' અવયવો</p></div></div>'
    return _outer(body,alt,uid,'a00-algebra-general-power')


def _selfcheck(alt,uid):
    objectives = (
        'ચલ અને બીજગણિતનાં પ્રતીકોનો ઉપયોગ કરવો.',
        'પદાવલીઓ અને સમીકરણો ઓળખવાં.',
        'ઘાતાંકવાળી પદાવલીઓ સરળ કરવી.',
        'ક્રિયાઓના ક્રમનો ઉપયોગ કરીને પદાવલીઓ સરળ કરવી.',
    )
    body = '<p style="margin:0 0 8px;font-weight:700">હું આ કરી શકું છું…</p>'
    for objective in objectives:
        body += ('<table style="width:100%;border-collapse:collapse;table-layout:fixed;font-size:14px;margin:0 0 12px">'
                 f'<caption style="text-align:left;font-size:17px;padding:6px 0">{objective}</caption><thead><tr>')
        for label in ('વિશ્વાસપૂર્વક','થોડી મદદથી','ના—મને સમજાતું નથી!'):
            body += f'<th scope="col" style="border:1px solid {TEAL};padding:7px;background:{PALE};overflow-wrap:anywhere">{label}</th>'
        body += '</tr></thead><tbody><tr>'
        body += ''.join(f'<td aria-label="ખાલી" style="border:1px solid {TEAL};height:35px">&#160;</td>' for _ in range(3))
        body += '</tr></tbody></table>'
    return _outer(body,alt,uid,'a00-algebra-selfcheck')


def render_figure(filename, alt, unique_id):
    """Return a localized figure, or None for verified math-only/unknown files."""
    uid = _uid(unique_id)
    if filename == PREFIX + '003.jpg':
        return _cars(alt,uid)
    if filename == PREFIX + '003_img.jpg':
        return _outer(_power_diagram('2','3',uid+'-power'),alt,uid,'a00-algebra-power')
    if filename in (PREFIX+'010_img.jpg',PREFIX+'020_img.jpg'):
        return _general(alt,uid)
    if filename == 'CNX_BMath_Figure_AppB_007.jpg':
        return _selfcheck(alt,uid)
    return None
